// Engineer Bibliography 2026 — quick reads: one short read per source document.
// Plain English, key facts and numbers only. Built from the source documents themselves.
var QUICK_READS = [
  {id:"MP-110.16-Hearing-Conservation", title:"M.P. 110.16 — Hearing Conservation Program", group:"ARs/Volume 1", what:"PFD's hearing protection program under OSHA 29 CFR 1910.95. It sets the noise levels that trigger protection, testing, and training, and what happens when hearing shifts.", points:["Action level: 85 dBA as an 8-hour time-weighted average (TWA) — at or above this, you are in the Hearing Conservation Program.", "Permissible exposure level: 90 dBA as an 8-hour TWA, with a 5 dB exchange (doubling) rate.", "Standard Threshold Shift (STS): a change of 10 dB or more, averaged at 2000, 3000, and 4000 Hz, in either ear versus the baseline audiogram.", "Hearing protectors must be available to all members exposed to 85 dBA or above, at no cost, and must attenuate noise to below 85 dBA.", "Hearing protection is mandatory at 85 dBA or above; also for members with no baseline audiogram at 85 dBA or above, and for members with an STS of 10 dB or greater.", "Noise reference points: PASS alarm 93 dB, chain saw/air horn 110 dB, fire engine/ambulance siren 120 dB, threshold for pain 120 dB, jackhammer 130 dB.", "Baseline audiometric exam within 30 working days of exposure at 85 dBA or above; no loud noise exposure for at least 14 hours before the exam (or wear hearing protection).", "An STS must be retested within 30 days to confirm; if confirmed, the member is notified in writing within 21 days and scheduled to see an audiologist.", "Members exposed at 85 dBA or above must be trained annually on the effects of noise, hearing protectors, and audiometric testing.", "Noise exposure records are kept 2 years; audiometric test records are kept for the duration of employment plus 30 years."]},
  {id:"Professional-Standards-Guide", title:"Professional Standards Guide", group:"ARs/Volume 1", what:"The PFD Way in writing — the customer-service and professionalism standard every member is held to, on and off duty. It is the guide behind M.P. 102.01's Rules of Conduct.", points:["Core idea: our customers see the uniform, not the rank — every member is held to the same standard of customer service.", "In most cases crews reach the scene of an emergency in about four minutes — that makes us the principal safety net for our citizens.", "Our customers are not an interruption in our work…they are our work.", "Sloppy uniforms, inappropriate language, and unprofessional behavior have no place in the Phoenix Fire Department.", "The PFD Way rests on six cornerstones: 1. Make the Commitment, 2. Be Accountable, 3. Be Self-Disciplined, 4. Be a Responsible Leader, 5. Maintain a Positive Environment, 6. The RBO Process.", "Self-discipline extends off duty and to the internet and social media — if you identify as a PFD member in a social media profile, that site becomes an extension of the workplace.", "Discipline, when needed, is corrective, progressive, and lawful; the PFD Way is second-chance management designed to return a member to positive, productive behavior.", "Leaders put safety first, closely followed by professionalism and courtesy; it is everyone's responsibility to stop dangerous, negative, and unprofessional behaviors whenever encountered.", "Positive environment behaviors: Consideration, Discretion, Acceptance, Unity. Don't talk about members behind their backs; there are two sides to every story.", "The RBO (Relationships By Objective) process brings Labor (Local 493) and Management together to work issues and reach agreements without damaging relationships — 'We will never sacrifice a relationship for an outcome.'"]},
  {id:"AR-2.96-Driver-Qualification", title:"AR 2.96 — Driver Qualification", group:"ARs/Volume 1", what:"Citywide rule on who can drive on City business and what happens when a driving record goes bad. It covers license standards, reporting duties, and the discipline tied to driving.", points:["Acceptable driving record = 5 or fewer points in the previous 12 months.", "8+ points in the previous 36 months, a DUI conviction in 36 months, or a license suspended/cancelled/revoked for a moving violation in 36 months blocks hiring, promotion, or transfer into a driving position.", "Employees must carry the appropriate valid license in physical possession (or Arizona Mobile ID) while driving on City business.", "Notify MVD of an address change within 10 days.", "Immediately notify your supervisor of a DUI citation/arrest or any license status change, no later than before the start of your next normally scheduled work shift — leave does not exempt you.", "Never drive on City business with a suspended, cancelled, disqualified, expired, restricted, revoked, or refused license.", "Driving record reviewed at least once a year, right before the performance appraisal; 6-8 points = Supervisory Counseling, 9-12 = Written Reprimand, 13+ = discipline up to suspension, demotion, or dismissal.", "DUI while driving on City business or in a City vehicle = dismissal.", "Failing to notify a supervisor of a suspended/revoked license or DUI and driving anyway = minimum 3-day suspension.", "License suspended 30 days or less = removed from driving immediately, may get a temporary non-driving assignment; 31 days or more = may be placed on unpaid leave up to 60 days."]},
  {id:"MP-102.01-Rules-of-Conduct", title:"M.P. 102.01 — Rules of Conduct", group:"ARs/Volume 1", what:"The conduct standard for every PFD member, alongside the PFD Way. Every member is expected to regulate their own conduct in a positive, productive, mature way.", points:["Failure to follow these rules can bring discipline from counseling up to dismissal.", "All members shall: follow Operations Manuals and City directives; protect the public on and off duty; always conduct themselves to reflect credit on the Department; keep themselves informed and physically fit; obey the law; take care of Department equipment and property.", "Supervisors manage in an effective, considerate manner; subordinates follow instructions in a positive, cooperative manner.", "Members shall NOT: fight; steal; abuse sick leave; engage in a conflict of interest or use their position for personal gain; do anything detrimental to the Department.", "Members shall NOT use alcoholic beverages, debilitating drugs, or any substance that could impair physical or mental capacities while on duty.", "Members shall NOT engage in any sexual activity while on duty."]},
  {id:"MP-102.05-Employee-Discipline", title:"M.P. 102.05 — Employee Discipline", group:"ARs/Volume 1", what:"How supervisors handle corrective action and discipline. Discipline is corrective, progressive, and lawful, with the goal of restoring the employee to positive, productive status.", points:["Primary goal of corrective/disciplinary action: improve performance, efficiency, and morale.", "Progressive: may start with Coaching or Supervisory Counseling and escalate to written reprimand, suspension without pay, demotion, or dismissal — but any level can be applied depending on severity, regardless of prior actions.", "Coaching is the least severe form, verbal or written, conversational in tone; Supervisory Counseling is more formal, in memo form, and cannot cite specific policy numbers (it is not grievable).", "Before taking disciplinary action, supervisors must seek approval from superiors and Fire Human Resources and be ready to justify the decision.", "All disciplinary investigations are confidential while in process; media inquiries go to the Fire Chief or Chief of Human Resources.", "The Deputy Chief of Training must be notified of any disciplinary action involving a probationary firefighter or trainee.", "The Fire Chief makes the final decision on suspensions, demotions, or dismissals.", "An employee's signature on discipline acknowledges receipt and understanding, not agreement; refusal to sign is not grounds for additional discipline — get a witness signature instead.", "Any suspension, demotion, or dismissal can be appealed to the Civil Service Board within 14 days of receiving notice, or 21 days from the date of certified mailing.", "Bargaining-unit employees have the right to Union representation during investigations and disciplinary actions if they choose."]},
  {id:"MP-102.05B-Complaint-Management", title:"M.P. 102.05B — Complaint Management Process", group:"ARs/Volume 1", what:"How PFD takes in, triages, and investigates complaints of misconduct. Every allegation of misconduct is thoroughly investigated before any discipline is issued.", points:["Complaints may come in any way — in person, phone, email, mail, anonymous — and employees shall not discourage, interfere with, or delay a complainant from filing.", "Four complaint types: Formal Complaint (policy violation), Customer Service (no clear violation, wants a supervisor talk), Information Only (no violation, no contact wanted), Projects (missing property or admin tasks).", "Four findings: Substantiated, Partially Substantiated, Unsubstantiated, Inconclusive — all judged on preponderance of evidence (more likely than not).", "Complaints are documented on the PFD Complaint Form and forwarded to OSI for triage; OSI assigns a case number and does fact-finding.", "OSI or the investigator must contact the complainant within 72 hours of receiving the complaint; all contact is logged and kept in the case file.", "If a criminal element is found, OSI immediately refers the case to the Police Department's Special Investigations Division (SID).", "Investigations should be completed within 90 days, with extensions only in complex cases with documented reasons.", "Employees must be told of their right to representation but must request it; NOIs are issued only when there is reasonable belief discipline may result.", "Garrity protections apply when applicable — compelled statements in admin investigations cannot be used in criminal proceedings.", "Interviews are sequenced Complainant → Witnesses → Respondent, and are recorded in their entirety; failure to cooperate is a separate basis for discipline, including dismissal."]},
  {id:"MP-103.02-Sick-Leave-56-Hour", title:"M.P. 103.02 — Sick Leave, 56-Hour Members", group:"ARs/Volume 1", what:"The sick leave rules for 56-hour members: how to call in sick, what to do while on sick leave, and when proof of treatment is required.", points:["Call in sick no later than 0530 hours on the day sick leave begins — in person or by phone to South Shift Command at 262-SICK (7425). No voicemail option; you must talk to a South Shift Command or ERSO staff member.", "Day-of call-ins go between 0430-0530 hours; call-ins before your scheduled workday can be made 0800-2000 hours.", "Be ready to give your name, assignment, reason for being sick, and a contact number.", "If you need more than one shift off, notify South Shift Command before each work shift.", "On sick leave you must stay home in a recuperative manner — no other work or recreational activities; time for a doctor visit or medicine is allowed, and documented therapy prescribed by a physician is allowed.", "Proof of medical treatment is required for leave over 2 shifts (48 hours), and after 6 sick leave occurrences in the previous 12 months the Battalion Chief may require proof for any future illness.", "An occurrence = any sick leave time over 4 hours used consecutively before returning to work.", "A member who cannot be contacted on two consecutive attempts must complete a sick leave non-contact memo on return to duty.", "Medical treatment slips are signed at the Battalion Office no more than 2 shifts after return to duty.", "Battalion Chiefs are responsible for contacting each member on sick leave each duty day they are off, unless daily contact is waived (extended leave, illness making contact unnecessary, or other substantial reason noted on Form 90-18D)."]},
  {id:"MP-103.05-Shift-Trades", title:"M.P. 103.05 — Shift Trades (AWRs)", group:"ARs/Volume 1", what:"The rules for trading shifts (AWRs). AWRs are a privilege, not a right — they can be suspended or revoked if procedures are violated.", points:["Maximum 45 shift exchanges per employee in a contract year.", "All AWRs need Fire Chief or designee approval and must follow Department Procedures; members must be current on all certifications and required training before approval.", "Shift exchanges do not qualify for premium overtime and cannot be repaid in any other form of compensation.", "Shifts are exchanged with the same EMS classification and rank; an AWR will not be approved if either the acquired or payback shift cannot be worked due to an EMS/rank conflict.", "The employee providing relief must complete the TeleStaff entry before 10pm the day prior to the AWR, including both members' information; late entries must be communicated to SSC staff between 0500-0600 on the day of the shift.", "All AWRs must be repaid within the 12-month contract year; AWRs acquired in June get 30 days beyond the contract year to pay back.", "Once the relief employee completes the TeleStaff entry, FULL RESPONSIBILITY for that shift is theirs — if they cannot work it, they must find someone qualified; if they are on unpaid leave or no longer employed, responsibility returns to the person who requested relief.", "Failure to provide relief = loss of vacation time equal to the cost of filling the position, and may cost the AWR privilege.", "Partial shift AWRs of 4 hours or more follow the same procedure as a full 24-hour trade; under 4 hours needs no TeleStaff entry but still needs prior supervisor approval.", "Probationary firefighters can start exchanging AWRs once approved to work overtime and satisfactorily working in an operations assignment."]},
  {id:"MP-103.07-Max-Allowable-Hours", title:"M.P. 103.07 — Maximum Allowable Hours Worked", group:"ARs/Volume 1", what:"The fatigue rule: how many consecutive shifts a member can work. Fatigue from extended work without rest can impair size-up, deployment, BLS/ALS skills, and defensive driving.", points:["Members shall not work more than 3 consecutive 24-hour shifts (or the equivalent), with or without partial leave.", "After 3 consecutive shifts, a member must be off duty a full 24 hours before working again.", "Taking partial shift leave of any kind does NOT exclude a member from this policy.", "A partial of 16 hours or more counts as a full 24-hour shift; working both an AM and PM overtime opportunity on the same day also counts as a 24-hour shift.", "It is the member's responsibility to schedule extra work so the policy is not violated and they stay available for their regularly assigned shift.", "A member found in violation will be relieved from duty and replaced by South Shift Command for the remainder of that shift.", "Passing up a constant staffing shift because of this policy is NOT charged as a 'refusal' or a 'pass' — but the member must tell the Shift Commander about the conflict when called.", "Members must be available to work assigned ERP days; being unable to work an ERP day because of a Maximum Allowable Hours violation counts as an ERP refusal."]},
  {id:"MP-201.00-Customer-Service", title:"M.P. 201.00 — Customer Service Management", group:"Volume 2", what:"The regional customer-service procedure for the CALSSRC Automatic Aid System. Our mission and number one priority is to deliver the best customer service possible on every call.", points:["CALSSRC defines the customer as any person who receives our services and anyone we have dealings with — including family, bystanders, people who visit our workplace, and our own members.", "Treat all customers with respect, kindness, patience, and consideration; respond quickly, skillfully, and positively to every customer.", "Deal with the customer's situation as an urgent event, from the time we know about it until it is over.", "Added value = going beyond standard quick, effective, professional service to create a feeling that the customer was the most important person we served all day.", "You are empowered to provide exceptional customer service — don't ask permission — if it is: right for the customer, right for the department, legal/ethical/nice, safe, on your organizational level, something you will be accountable for, and consistent with department values and policies.", "Give the customer your undivided attention and take a moment, when appropriate, to educate them about what we do and why.", "Company and Command Officers must provide a work environment where exceptional customer service and added value are the result of a refined system.", "Benefits of exceptional service: it saves lives and property, builds trust in the community, secures resources, improves job satisfaction, and eliminates bad press, liability, and extra paperwork."]},
  {id:"MP-201.01-Command-Procedures", title:"M.P. 201.01 — Command Procedures", group:"Volume 2", what:"The big one — how Command is established, run, and transferred at every incident. We always operate within the Incident Command System, from the first unit on scene to a full NIMS organization.", points:["Purpose: fix responsibility for Command on a certain individual, establish strong visible Command from the onset, define the incident organization, process information for decisions, and provide for orderly transfer of Command.", "Shift Commanders (South/West/East Deputies) manage Battalions and serve as Senior Advisor on the Command Team at first and greater alarms.", "Battalion Chiefs manage companies and supervise company officers; they take IC when appropriate and serve as Sector Officers when appropriate.", "Company Officers (Captains) take IC when appropriate, serve as Sector Officers, and manage task-level activities.", "Span of control: an IC can usually effectively manage five sectors, and should never exceed seven sectors.", "Command shall not be transferred to an officer who is not on the scene — passing Command to someone off scene creates a gap in the Command process.", "Fast-attack-mobile Command is a brief mode — it should not last more than a few minutes — ending when the situation stabilizes, Command is transferred, or the IC moves to a stationary exterior command position.", "Transfer of Command is an orderly process to subsequent arriving officers, so the incident can scale seamlessly from a Type 5/4 incident to a Type 3/2/1 (NIMS) incident."]},
  {id:"MP-201.01A-In-Transit-On-Deck", title:"In-Transit, On Deck, Company Recycle", group:"Volume 2", what:"The standard way companies move from staging to their work area, layer as On-Deck reserves inside a sector, and recycle air and water without leaving their assignment.", points:["In Transit is the time from receiving an order until the company reaches its assignment area; the company officer monitors the tactical radio channel while In Transit.", "On arrival, the company officer announces to the IC (e.g. \"E-1 On Deck in North Sector\") or reports face-to-face to the Sector Officer that the company is intact and in its area.", "On-Deck is a tactical function inside a Sector for layering resources in forward positions — it is NOT an independent forward staging location.", "On-Deck crews sit just outside the immediate hazard zone, stay intact and ready, monitor the tactical channel at all times, and size up their area (entrances/exits, conditions, interior crew locations, who is on each line).", "Most likely On-Deck jobs: Rapid Intervention Crew, reinforcing a position, crew relief, or any other tactical position the IC assigns.", "When used as a relief crew, the On-Deck company officer does a face-to-face handoff with the exiting officer covering interior conditions, routing, obstructions, tools needed, and sector objectives.", "Recycling is air replacement and re-hydration while keeping the sector assignment — it does not need communication with the IC; the Sector Officer owns it.", "If conditions permit, a company work cycle can be up to 2 to 3 air cylinders; companies should forecast their time in a sector and bring spare cylinders."]},
  {id:"MP-201.01C-Risk-Management-Safety", title:"M.P. 201.01C — Risk Management and Safety", group:"Volume 2", what:"The Risk Management Plan every member works under at every emergency incident. It answers 'why are we taking risk at this incident?' — savable lives, savable property, or nothing worth risking.", points:["We WILL risk our lives a lot, in a calculated manner, to save savable lives.", "We WILL risk our lives a little, in a calculated manner, to save savable property.", "We WILL NOT risk our lives at all for lives or property that are already lost.", "'Calculated manner' requires: Strategic Decision Making Model, Incident Command established, proper PPE, accountability system, safety procedures, continuous risk assessment by all members, uninterrupted communications.", "The plan is continuously re-assessed at all levels until all units leave the scene.", "Three questions set the risk level: Are there savable lives? Are there survivable environments or compartments? Do we have the resources and ability to affect a rescue and survive it?", "A quick, overwhelming attack from any reasonable position may be the best way to reduce risk and create a chance for rescue and firefighter survivability.", "If size-up shows neither savable lives nor savable property, no or very limited risk is taken within a defensive strategy.", "The plan applies to all hazards and incidents: large-scale medical, HazMat, technical rescue, and violent incidents."]},
  {id:"MP-201.01D-Fire-Behavior-Glossary", title:"M.P. 201.01D — Fire Behavior Glossary Reference", group:"Volume 2", what:"A fire behavior reference — the definitions and concepts behind how fire starts, grows, and kills. The terms here are the language of size-up, ventilation, and fire attack decisions.", points:["Fire is a rapid oxidation process; combustion is oxidation fast enough to produce heat and light.", "The fire triangle (fuel, heat, oxygen) is the oldest, simplest model; the fire tetrahedron adds the uninhibited chemical chain reaction.", "Pyrolysis is the chemical decomposition of a solid by heat; vaporization is how liquids turn to gas so they can burn.", "Heat moves by conduction, convection, and radiation — and fire is extinguished by removing one or more sides of the tetrahedron.", "Flammable liquid = flash point below 100°F; combustible liquid = flash point equal to or greater than 100°F.", "Fire point is the lowest temperature at which a liquid will ignite and achieve sustained burning.", "Vapor density greater than 1 = heavier than air, sinks and collects in low areas; less than 1 = lighter than air, rises.", "Incipient stage is the earliest stage — small fire, limited to the materials of ignition; it can transition to growth in seconds.", "Flashover is the simultaneous ignition of all combustible materials and pyrolysis gases in a compartment; temperatures typically exceed 1100°F, and it happens during the growth stage.", "Backdraft is a deflagration from the sudden introduction of air into a confined space with oxygen-deficient products of incomplete combustion; indicators include no visible flaming, pulsating smoke, grey-yellow smoke seeping around closed doors and windows, and very hot doors and windows."]},
  {id:"MP-201.03-Accountability", title:"M.P. 201.03 — Accountability", group:"Volume 2", what:"The passport accountability system — how Command, Sector Officers, Company Officers, and engineers track every firefighter in the hot zone, and how PARs confirm everyone is accounted for.", points:["It is the IC's responsibility to maintain awareness of the location and function of all companies and crews; the system applies anywhere SCBA is required.", "The passport is a bright yellow tag, about 3 by 4 inches, marked with company ID and shift, with each crewmember's nametag affixed; it rides in a pouch kept on the apparatus dash.", "Passports never enter the hot zone — they are delivered to the accountability location before entry and retrieved on exit.", "When a hoseline is charged, the engineer places the passport/pouch on the discharge gate — the pump panel becomes an accountability station, and the engineer becomes the accountability officer for crews on his lines.", "Ladder crews leave their passport on the apparatus dash for roof ventilation; for interior work they deliver it to the engine closest to their point of entry.", "Company Officers must keep the crew intact, know each firefighter's location and task, and watch the crew's exit air supply; the whole crew exits if an SCBA, radio, or safety-critical equipment fails in the hot zone.", "Every crew entering the hot zone must have a supervisor, and every member must have a radio. Crews go in together, stay together, and come out together — no freelancing.", "A PAR (Personnel Accountability Report) is a roll call confirming all members are accounted for and have adequate exit air supply.", "A PAR is required for: a missing/trapped firefighter, a change from offensive to defensive, a sudden hazardous event (flashover, backdraft, collapse, Mayday), an all clear, under control, every 30 minutes of elapsed time, and any time Command feels it is necessary.", "Passport accountability runs the whole incident and ends only after a 'fire under control' report plus a PAR for all crews; Command may extend it if visibility is still impaired or a significant hazard exists."]},
  {id:"MP-201.04-2-In-2-Out", title:"M.P. 201.04 — 2 In / 2 Out", group:"Volume 2", what:"The OSHA 2 in / 2 out rule (29 CFR 1910.134(g)(4)) as applied on Phoenix Regional incidents — two fully equipped firefighters ready outside whenever crews are on air inside an IDLH atmosphere.", points:["Once firefighters begin an interior attack on an interior structural fire, the atmosphere is assumed to be IDLH and 2 in / 2 out applies.", "The objective: fully equipped firefighters in position during the initial attack to react to a Mayday.", "2 in / 2 out is established any time firefighters are on air inside a structure and no other units have arrived.", "Standard exceptions at structure fires: (1) a reported or suspected life hazard where immediate action could prevent loss of life; (2) a fire in the incipient stage.", "An incipient stage fire is one in its initial stage that can be controlled or extinguished by portable extinguishers, Class II standpipe, or small hose systems without PPE or breathing apparatus.", "The 2 in / 2 out standard is met when the second arriving fire company arrives and is positioned on scene or in Level 1 staging.", "The only radio communication about 2 in / 2 out needed during initial deployment is when the standard is NOT met — and only the two exceptions above are acceptable reasons.", "One primary member of the 2 in / 2 out pair must be solely dedicated to tracking interior personnel and reacting to a Mayday; the second member may do other work in the hazard zone, including the engineer operating the pumper.", "For a four-person crew in fast attack, the plug person takes the primary 2 in / 2 out position and the engineer takes the secondary position.", "Any rescue effort is initiated as a team of 2, well communicated before action; Mayday response is managed with the Risk Management Plan."]},
  {id:"MP-201.06-3-Deep", title:"M.P. 201.06 — 3 Deep Deployment Model", group:"Volume 2", what:"How Command keeps enough resources ahead of the incident instead of falling into crisis management — deploy three deep, and call for more help early.", points:["Crisis management is when a situation grows faster than the response rate to it — the IC ends up with an out-of-control situation and inadequate resources.", "If the IC debates whether to call another alarm, call for it — if the extra resources are not needed, they can easily be put back in service.", "The 3-deep deployment model: Working, On-Deck, Recycle/Staged — Command must keep a tactical reserve of fire companies in forward positions, including a reserve for a firefighter rescue.", "Command should expand the incident organization through sectorization and use the 3-deep model for resources within those sectors.", "Use the greater alarm mechanism — it is the quickest, provides automatic move-ups, and supports the expanding incident; resist requesting help piecemeal.", "Additional alarms are struck sequentially: from a 3 & 1 assignment, to a 1st alarm, to a 2nd alarm, and so on.", "Call for additional resources at a rate that stays ahead of the incident — some situations move slowly, some very quickly.", "Command cannot call additional alarms and then manage those resources without expanding the incident organization through sectorization.", "Call more resources when: life hazard exceeds rescue/EMS capability, victims exceed removal/treatment capability, all companies are committed and the fire is not controlled, forces may be depleted by exhaustion, or Command anticipates running out of firefighters, apparatus, water, equipment, or command officers.", "Don't disregard fireground hunches — if Command instinctively feels the need for more resources, call for them."]},
  {id:"MP-202.01-Standard-Company-Functions", title:"M.P. 202.01 — Standard Company Functions", group:"Volume 2", what:"The standard job of each company type on the fireground — Engine, Ladder, Rescue, and Heavy Rescue — so Command can assign the right company to the right function and crews know what the other companies are doing.", points:["Standard functions organize basic fireground work by company type, assign each major function to the company that can best do it, and reduce the amount and detail of orders needed to get companies into action.", "Engine Company: size-up, assumption of Command, 360° assessment, search/rescue/treatment, forcible entry, stretch hose lines, operate nozzles, pump hose lines, loss control.", "Ladder Company/Tender: size-up, assumption of Command, 360° assessment, search/rescue/treatment, coordinated horizontal and vertical ventilation, forcible entry, raise ground ladders, access/check fire extension, utility control, lighting, ladder pipes (aerials/platforms only), overhaul, extrication, loss control.", "Rescue Company: transport sick and injured to hospitals; search, rescue, and treatment — while staying retrievable for victim treatment and transport; general firefighting duties as assigned.", "Heavy Rescue Company: all Engine and Ladder functions plus structural collapse/shoring and heavy lifting.", "Company Officers set the priority of their company's functions based on conditions and the Risk Management Plan, unless ordered otherwise by Command.", "Every company is expected to perform all basic functions safely within its capability — the list does not limit a company to only its listed functions.", "In Level 1 Staging, the first arriving Engine, Ladder or Heavy Rescue, and Rescue companies perform these functions as required and ordered by Command.", "If no Ladder company is available or it is delayed, Command should assign ladder functions to a Heavy Rescue or an Engine company."]},
  {id:"MP-202.02-Fireground-Factors", title:"Fireground Factors", group:"Volume 2", what:"The seven categories the IC uses to size up any incident and decide how the tactical objectives will be met.", points:["Size-up is an appraisal of the magnitude or dimensions of an event or incident — it is how the Critical Fireground Factors are established.", "The Critical Fireground Factors simplify complex information into 7 categories: Building, Fire, Occupancy, Life Hazard, Arrangement, Resources, and Other Factors/Conditions.", "It is unacceptable to begin operations before adequately performing size-up and considering the critical fireground factors.", "Size-up comes in three overlapping forms: Visual (what Command can see), Reconnaissance (send someone to check), and Preplanning/Familiarity (preplans, CAD/MDT).", "Fireground factors are dynamic — their relative importance changes through the incident, so Command must revise the action plan as information changes.", "Command will seldom have complete information during initial operations; efforts must continue to improve the information decisions are based on."]},
  {id:"MP-202.02A-Tactical-Objectives", title:"Tactical Objectives", group:"Volume 2", what:"The three things that must be completed to stabilize any incident — Rescue, Fire Control, and Property Conservation — and the benchmark announced for each.", points:["The three tactical objectives are Rescue, Fire Control, and Property Conservation — separate but interrelated, dealt with concurrently.", "Rescue: protect occupants, remove those threatened, and treat the injured.", "Fire Control: stop the forward progress of the fire and bring the fire under control.", "Property Conservation: stop or reduce primary or secondary damage to property.", "Benchmarks announced when each is reached: Rescue/primary search — \"All clear\"; Fire Control — \"Under control\"; Property Conservation — \"Loss stopped\".", "The umbrella of service — firefighter safety, customer service, and loss control — is an ongoing responsibility that is never finished with a benchmark."]},
  {id:"MP-202.02B-Fireground-Strategy", title:"Fireground Strategy", group:"Volume 2", what:"How the IC picks and manages the Offensive or Defensive strategy, including marginal situations and the switch to defensive.", points:["Every structure fire is Offensive or Defensive, declared by the IC; never run offensive and defensive in the same fire area at once.", "Risk Management Plan: risk our lives a lot, in a calculated manner, to save savable lives; a little to save savable property; not at all for lives or property already lost.", "A marginal situation is defensive conditions with a known rescue — a very short window to affect the rescue or discontinue and go defensive.", "The only reason to operate in a marginal situation is rescue.", "A change to defensive strategy is announced as \"Emergency Traffic\"; all personnel withdraw, maintain a safe distance, and a PAR is obtained.", "Master streams are the most effective defensive tactic; a standard master stream flow of at least 750 GPM is the guideline.", "Command must consider all seven sides of the fire: front, rear, both sides, top, bottom, and interior — a fire is not under control until all seven are addressed.", "Before entry, when possible, reset or darken down the fire with a straight stream on the ceiling for 15–30 seconds, then follow with an aggressive interior attack.", "It is better to go from offensive to defensive too soon rather than too late — if Command waits until the building is disassembling itself, Command is late."]},
  {id:"MP-202.02C-Rescue", title:"Rescue", group:"Volume 2", what:"How rescue is prioritized and run — primary and secondary search, the rescue order, and the remove-the-victim vs. remove-the-fire decision.", points:["Life safety is the highest tactical priority on the fireground and in all other hazard zones.", "The two greatest threats to victims are toxic exposure (smoke and gases — worse the higher the victim is) and thermal exposure (worse the closer and higher the victim is).", "Rescue efforts go in this order: most severely threatened, then the largest number (groups), then the remainder of the fire area, then the exposed areas.", "A primary search is a quick pass through all affected areas to verify removal/safety of occupants; time is the critical factor; completion is reported as \"All Clear\".", "A secondary search is a thorough search after initial fire control and ventilation, preferably by different companies; thoroughness, not time, is the critical factor.", "Use \"SEARCH & RESCUE\" when assigning a primary search over the radio; \"ALL CLEAR\" is only the completion report.", "Command must make the basic decision: remove the victims from the fire, or remove the fire from the victims — or both at once.", "Do not depend only on reports from residents or spectators to determine victim status — complete a primary search wherever entry is possible."]},
  {id:"MP-202.05-Fireground-Safety", title:"Fireground Safety", group:"Volume 2", what:"General safety rules for the fireground — control zones, tactical positioning, structural collapse warning signs, and evacuation.", points:["Risk Management Plan: risk our lives a lot, in a calculated manner, to save savable lives; a little to save savable property; not at all for lives or property already lost.", "Hot Zone = red, Warm Zone = yellow, Cold Zone = green, No-Entry Zone = red and white diagonal-striped or chevron tape.", "All firefighters in the Hot Zone work in crews of at least two, in PPE, with a radio on the correct tactical channel, and an assigned task.", "When laddering a roof, the ladder must extend 2'–3' above the roof line so roof personnel have a visible means of egress.", "A 100-foot length of unprotected steel will expand 9 inches when heated to 1100°F.", "If heavy fire conditions still exist after 10–15 minutes of interior operations, Command should carefully evaluate structural conditions and be ready to withdraw crews.", "\"Emergency Traffic\" is only for an imminent hazard or one that just occurred; on the evacuation order the company officer assembles the crew, exits, and reports a PAR for all crew members.", "Do not operate exterior master streams into an area where interior crews are operating; ground crews must be notified and evacuated before ladder pipes go into operation."]},
  {id:"MP-202.05B-SCBA", title:"Self-Contained Breathing Apparatus", group:"Volume 2", what:"When SCBA must be worn, the facepiece seal rule, and who is responsible for keeping each pack ready.", points:["Every member expected to work in contaminated atmospheres must be equipped with SCBA and trained in its proper use and maintenance.", "Members must achieve a non-leaking facepiece-to-skin seal with the mask; facial hair is not allowed where the facepiece is designed to seal.", "Each Operations member is accountable for one SCBA and checks it at the beginning of each shift, after each use, and whenever needed to keep it ready.", "A SCBA found functioning improperly is taken out of service, red-tagged, reported, and replaced immediately.", "SCBA is used in any contaminated atmosphere, one that may suddenly become contaminated, one that is oxygen deficient, or one suspected of being either.", "Premature removal of SCBA must be avoided at all times — especially during overhaul, when smoldering materials produce more toxic substances including carcinogens.", "If there is any doubt about respiratory safety, SCBA use is maintained until the atmosphere is established safe by testing.", "Each member is evaluated annually in SCBA use and must demonstrate an effective facepiece-to-skin seal."]},
  {id:"MP-202.06-Roof-Sector", title:"Roof Sector", group:"Volume 2", what:"What Roof Sector does — roof size-up, which roofs are off-limits, and how vertical ventilation is coordinated with the fire attack.", points:["Roof Sector's key jobs: determine roof type, integrity, loads, attic/void spaces, and fire extension — and coordinate vertical ventilation with the IC and interior crews.", "Roof crews enter from an established safe area and must have a secondary means of egress or a safe refuge on an unexposed, sound roof surface.", "No firefighter operates on or under a bowstring roof if fire has penetrated the attic space involving the trusses or roof structure in any way.", "Ladder companies will not operate on pitched metal roofs.", "No firefighters operate on a roof to ventilate a single-family or duplex covered with concrete or clay tile — use horizontal or positive pressure ventilation instead.", "No firefighter operates on a roof with photovoltaic roof tiles.", "Vertical ventilation is most efficient directly over the fire compartment, and only helps if water is being flowed on the fire at or near the same time — otherwise conditions get worse fast.", "When more vertical ventilation is needed, do not make holes larger — cut additional holes a safe distance away, moving toward safer areas with each hole."]},
  {id:"MP-202.08-Rehabilitation", title:"Rehabilitation Sector", group:"Volume 2", what:"How Rehab Sector is set up and run — the four functions, the vital-sign numbers, and when a firefighter is cleared to go back to work.", points:["No member will be permitted to continue emergency operations beyond safe levels of physical or mental exertion; Rehab exists to prevent injury from extended operations under adverse conditions.", "Rehab provides assessment of vital signs, rest/hydration/refreshments/temperature regulation, medical evaluation and treatment, transport, and reassignment.", "A Rehab truck is dispatched on all First Alarm and greater incidents, or when a heat stress advisory is in effect.", "Rehab has one entry point and four functions: A Assessment, B Hydration and Replenishment, C Medical Treatment and Transport, D Documentation.", "Any member with a pulse over 120 at entry is recorded and tracked, then re-evaluated after 20 minutes of rest and hydration.", "No responder returns to duty until the pulse is below 100 bpm after 20 minutes of rest; a pulse still over 100 gets ALS evaluation and a 12-lead EKG.", "Return-to-duty standards: heart rate below 100 bpm with no irregular beats, systolic BP below 160, diastolic below 100, respiratory rate 12–20, no abnormal neuro findings, no complaints.", "Pulse oximetry must be above 92% to return to operations; body temperature over 99.5°F after 20 minutes may mean no return to duty and transport to a hospital.", "Members assigned to Rehab do not report back to their old sector — they are reassigned only by Command after being cleared by Rehab."]},
  {id:"MP-202.11-High-Rise", title:"High-Rise Plans", group:"Volume 2", what:"The full playbook for high-rise fires — definition, sector setup, stairwell roles, standpipe hose lines, elevators, and air management.", points:["A high-rise is 6 elevator stops or greater, or 75 feet in height or greater.", "Consider a minimum 3rd alarm assignment in working high-rise fires.", "Elevators will not be used as a means of rescue in smoke or fire conditions.", "First arriving company assumes Command, finds the Fire Control Room/alarm panel, and establishes Building Systems Sector; FD Rescues should not take command if arriving first.", "The fire floor on-deck area is in a clean environment a minimum of 2 floors below the fire floor; all fire floor operations start from the on-deck floor.", "Fire floor needs a minimum of three, preferably four, initial companies; the attack line connects at the closest standpipe below the fire floor, with backup and stairwell protection lines one floor below that.", "Attack lines: 1¾\", 2\", or 2½\" for the initial line; backup and stairwell protection are 2½\" with smooth bore nozzles; 2\" lines give 250+ gpm and meet the NFPA 1710 standard of 500 gpm with two lines on the fire floor.", "Elevators are typically not used if the fire floor is 10 or less; freight elevators are preferable; the elevator must be Phase II capable with a dedicated operator and the roof hatch opened.", "Crews entering the building bring a minimum of 1 spare SCBA bottle per crewmember and collectively check air every 5 floors when ascending stairs.", "Hazard Sector monitors O2 and CO at the on-deck location; smoke and CO can bank down in stairwells from the reverse stack effect."]},
  {id:"MP-202.12A-Salvage", title:"Salvage", group:"Volume 2", what:"How to stop and limit loss to property and contents during and after the fire — what salvage is, where it starts, and what drives the priorities.", points:["Salvage is stopping direct and indirect fire damage and reasonably mitigating the effects of firefighting operations — water, smoke, and suppression damage count too.", "Salvage objectives: reasonably stop or reduce the sources of damage, and reasonably protect or remove contents.", "Command provides for salvage at all fires or other incidents posing potential damage to property.", "Salvage starts in the areas most severely threatened — usually directly adjacent to or below the fire — then expands outward.", "When removal is not practical, contents are grouped in the center of rooms, raised off the floor, and covered for maximum practical protection.", "Value, not just price, drives salvage priorities — business records or family photos can be worth far more than their dollar cost.", "Common salvage equipment: salvage covers and boxes, rolled plastic, hall runners, brooms, and squeegees.", "Command or the Sector Officer should meet with the property owner early to identify high-value/priority items; escorting the owner through the building when safe can help loss control."]},
  {id:"MP-202.12B-Overhaul", title:"Overhaul", group:"Volume 2", what:"Finding hidden fire after knockdown, the special problem of cellulose insulation, and why defensive fires get no standard overhaul.", points:["Overhaul is the search for hidden fires and the assessment of final extinguishment after the main body of fire is knocked down; the goal is to reduce secondary fires, control loss, and stabilize the scene.", "Hot spots can get buried deep inside cellulose insulation where they can lie before breaking into fire — remove or wet down as much insulation as reasonably possible.", "Standard overhaul is NOT conducted on structures declared Defensive Fires; crews keep applying water to hidden fire from exterior positions until all fire is out.", "Roof ventilation holes and broken windows should be covered to reduce weather damage and deter vandalism; rolled plastic is ideal for this purpose.", "The company officer last leaving the scene is responsible for fire extinguishment when possible; the IC schedules post-incident drive-by/walk-through inspections.", "A post-incident inspection is done before the last unit leaves the scene; the IC may waive further inspections if a fire watch is in place.", "Overhaul crews should compare preserving evidence against the need to remove debris and extinguish fire — in some cases monitor spot fires until investigators arrive."]},
  {id:"MP-202.12E-Water-Supply-Fire-Stream", title:"Water Supply and Fire Stream Management", group:"Volume 2", what:"Getting enough water to the fire — supply lays, pumped water and big-water evolutions, hose and nozzle flows, and stream selection.", points:["An unsupported forward supply lay of 500 feet of 4-inch supply line can flow 800 GPM — usually enough for most initial attack operations without pumped water.", "First due engines with any evidence of a working fire should secure a water supply, unless there is a known/suspected rescue, the fire location is unsure, or it is a high-rise.", "Aerial apparatus typically flow 1000 gpm per deck gun; most aerial platforms have 2 deck guns and are 1000+ gpm appliances.", "A master stream at 1000 gpm delivers 8,340 pounds of water per minute (139 pounds per second) — enough to adversely affect structural stability.", "2-inch smooth bore nozzle with a 1 1/16-inch tip: 260 GPM at 60 psi nozzle pressure. 2½-inch smooth bore with a 1 3/16-inch tip: 265 GPM at 40 psi.", "Solid/straight streams give greater penetration, reach, striking power, and cooling with less steam; fog patterns give shorter reach, smaller droplets, more air entrainment, and more steam.", "Fire is most effectively extinguished by water on the interior surfaces of a burning compartment first, then on the burning fuels — best with a straight or solid bore stream.", "When switching from offensive to defensive, shut down smaller (1¾-inch) hand lines and close their discharges so firefighters do not creep back into the hazard zone.", "Back up lines should match or exceed the water volume of the initial attack line."]},
  {id:"MP-202.15-Brush-Wildland", title:"Brush/Wildland Fire", group:"Volume 2", what:"How Phoenix Regional handles brush and wildland fires — LCES, Red Flag conditions, alarm assignments, direct vs. indirect attack, and mop-up.", points:["Firefighter safety is the primary objective for brush/wildland incidents; wildland fires are low frequency, high risk.", "LCES — Lookouts, Communications, Escape Routes, Safety Zones — must be in place at all times, and before any suppression operations.", "A Red Flag Warning means sustained winds of 20 mph or more and relative humidity of 20% or less; fire danger is Very High or Extreme.", "A working First Alarm Brush assignment or greater is deemed a wildland fire and gets additional resources; Dispatch activates the \"All Call\" and contacts the Arizona Department of Forestry and Fire Management.", "Any department using a drone during a brush/wildland fire must land it immediately as soon as any aircraft has been ordered — no aircraft can fly on a fire if a drone is up.", "Direct attack: \"anchor and flank\" from a safe anchor point, and attack from the burned (black) side — \"one foot in the black\" — not head-on from the unburned side.", "The three factors driving wildland fire behavior are weather, fuel, and topography; fire burns uphill much more rapidly than downhill.", "During a normal day, local winds change 180 degrees near midday; fire spread slows in the evening as humidity increases (25%) and increases midmorning as humidity decreases (15%).", "First Alarm Brush assignment: 5 engines, 4 brush trucks, 2 water tenders, 3 command officers, 1 shift commander, 1 command van, 1 safety officer, 1 rehab unit, 1 canteen unit, 1 rescue, 2 CXX19.", "Mop-up: put out all embers and sparks so none cross the fire line; during rehab of mop-up crews, at least two firefighters remain in the area to monitor for re-ignition."]},
  {id:"MP-202.16-Car-Fires", title:"Car Fires", group:"Volume 2", what:"Tactics for vehicle fires, with the big emphasis on electric and hybrid vehicles — battery fires, water needs, attack angle, and post-fire tow rules.", points:["There is no such thing as a standard vehicle fire; crews must size up and identify the vehicle type — EV, hybrid, LPG, CNG, hydrogen, or autonomous — before committing.", "Minimum protection is full protective clothing breathing air from SCBA; captains must wear full PPE to directly supervise crews.", "Minimum attack line for a vehicle fire is the 1¾-inch handline, attacked from a 45-degree angle; first water goes to the passenger compartment and an all clear is obtained.", "Apparatus should be placed upwind and uphill if possible, using the apparatus as a barrier to shield the scene from traffic.", "An EV battery fire can take 3,000 gallons or more of water to fully extinguish and cool the batteries — an uninterrupted water supply is required.", "Attack an EV fire at a 45-degree angle starting 40 feet away and move forward; batteries vent below the rocker panels and out the sides.", "EV batteries are always considered energized; never cut into or puncture the battery pack; AFFF is contraindicated and Class A foam reduces water's cooling effect.", "EVs must show a stable or reducing battery temperature for at least one hour before being turned over to a tow company; stored EVs need a 50-foot clear space around them, never inside a building.", "Energy-absorbing bumpers can release suddenly when heated and have been known to travel 25 feet.", "A vehicle fire in a parking garage upgrades the assignment to a 3 & 1; supporting the sprinkler system is a high priority."]},
  {id:"MP-202.20-Mid-Rise", title:"Mid Rise Operations", group:"Volume 2", what:"The unique problems of mid-rise buildings (3+ stories, under 75 feet) — sealed construction, spotty standpipes and sprinklers, long hose stretches, and wood-frame upper floors.", points:["A mid-rise is anything below 75 feet in height and greater than 3 stories — different fire protection standards than high-rise, and not the same across all mid-rises.", "Nothing showing means nothing — a mid-rise can have a serious fire with no external signs on arrival, because the buildings are tightly sealed.", "Mid-rises typically have no Fire Control Room, no fire pumps, and no floor/stairwell pressurization; city water pressure feeds the wet sprinkler and standpipe systems.", "Standpipes may not be in every stairwell, and some standpipe connections can be up to 200 feet apart; FDC and standpipe connections may have KNOX locking caps needing \"dog bone\" keys.", "The building layout can require hose stretches of more than 150 feet — a clear assessment of the action and the risk management position is critical.", "No company should operate inside beyond its ability to retreat to an area of safe refuge before its low air alarm goes off.", "Modern residential mid-rises combine masonry/concrete lower levels with wood-framed upper levels; fire in the structural members is very dangerous and must be reported to Command immediately.", "Mid-rises built since 2002 are required to be sprinklered; the fire code requires keys only for pools, utility/mechanical/electrical rooms, sprinkler riser room, alarm panel rooms, stairwells, roof access, and non-standard elevator keys.", "Fire in floor joist spaces is a floor-failure risk; bathrooms and kitchens are often a concern, and the code requires sprinklers in open-web joist spaces but not in solid joist (TJI) spaces.", "All mid-rise operations are always conducted on hazard zone radio channels; radio communications may need relay workarounds like high-rise buildings."]},
  {id:"MP-204.01-HazMat", title:"Hazardous Materials", group:"Volume 2", what:"How hazmat incidents are sized up and controlled — the SDM, apparatus spotting, the Hot Zone and Limited Access Zone, and the action plan.", points:["The Strategic Decision-Making Model (SDM) must be applied on every incident, hazmat included — it starts with size-up of life safety, exposure duration, chemical properties, release size, and containment already in place.", "Never spot apparatus near a potential blast zone, over a storm drain, downwind, or downhill of a hazmat incident; staged companies must be upwind, uphill, and outside any potential blast zone.", "The DOT Emergency Response Guide is used by first arriving companies as a resource for spotting apparatus at a safe distance.", "Depending on the material released, turnouts and an SCBA may NOT protect the member — proper PPE level must be matched to the hazard.", "The Hot Zone is the area of immediate danger; only personnel with proper PPE, radios, and an assignment enter, and it is identified by white/red hazard zone tape.", "The Limited Access Zone (LAZ) is the larger area around the Hot Zone with a lesser degree of risk; all civilians are removed from it and the Police enforce its limits.", "When toxic or irritant vapors are carried downwind, sheltering in place — indoors, windows and doors closed — may be more effective than evacuating.", "The action plan must provide for safety of all fire personnel, evacuation of the endangered area, control of the situation, stabilization of the hazmat, and disposal or removal."]},
  {id:"MP-204.09-Trench-Rescue", title:"Trench Rescue Operations", group:"Volume 2", what:"The phased approach to trench rescue — arrival distances, making the area safe, shoring, victim removal, and termination.", points:["No personnel shall be allowed into an unsafe trench or excavation; an excavation is any depression, hole, trench, or earth wall, man-made or natural, of four feet or greater.", "Trench collapses are usually caused by unstable soil plus improper or inadequate shoring; removing soil, adding weight near the edge, vibration, rain, or just time passing can cause additional collapse at any time.", "Apparatus must stay at least 50 feet from the trench failure; Level 1 staging is at least 150 feet away.", "Pre-entry: hazard zone perimeter 50 feet from the collapse, non-essential civilians at least 150 feet away, non-essential traffic re-routed at least 300 feet away, heavy equipment shut down within 300 feet.", "The first arriving TRT unit staffed with a TRT Company Officer is assigned Rescue Sector; the Technical Advisor joins the Command Team before any rescue plan is implemented.", "Phases: Arrival, Pre-entry operations, Entry operations, Termination — only trained Technical Rescue Technicians do pre-entry and entry work under Rescue Sector.", "Entry: at least 2 ladders into the trench, no more than 50 feet apart; create a safe zone in the non-collapsed area with an approved shoring system before removing dirt from the collapse zone.", "With a collapse, uncover the victim to below the diaphragm with small shovels, buckets, or by hand, assess, then fully uncover, package, and remove.", "Termination: remove tools, equipment, and the shoring system last-in/first-out; in a fatality, consider leaving everything in place until the investigation is complete."]},
  {id:"MP-205.01-Communications", title:"Communications", group:"Volume 2", what:"The dispatch and radio rulebook: how calls are taken, units are picked, and how crews talk on the radio and report on scene.", points:["PFD dispatches the closest available unit with the required capabilities; when in doubt whether a call needs a response, the policy is to dispatch.", "A unit can fill only one primary requirement, but can fill more than one secondary requirement.", "If Deployment gets no acknowledgement within 1 minute it asks again; a cover assignment goes out if there is no reply within 2 minutes.", "All fire and ALS EMS responses are Code 3 unless told otherwise; freeway responses are Code 2 on the mainline.", "A unit on a Code 2 AOI call can be pre-empted for a higher-priority call; after 10 minutes responding it flips to Unavailable On Incident.", "Working Fire and Working Haz Mat incidents get an elapsed-time notification every 5 minutes until Under Control.", "Only Command can release companies from an incident.", "'May Day' is used only for a lost or trapped firefighter; 'Emergency Traffic' gets the highest communications priority and the air belongs to that unit.", "Radio code 906 means a fire unit needs immediate police assistance; plain language is preferred over codes.", "The standard on-scene report covers: clear alarm, unit on scene, building description, conditions, action taken, strategy, and Command name."]},
  {id:"MP-205.02-EMS-Dispatch", title:"EMS Dispatch Procedures", group:"Volume 2", what:"Which medical calls get a fire unit plus a paramedic unit, and which get a fire unit only.", points:["Policy: an adequate, early and pessimistic response of the closest units.", "Cardiac/respiratory arrest, chest pain, difficulty breathing, stroke, shootings, stabbings, overdose, seizures and the other listed emergencies get the closest suppression unit backed up by a paramedic unit.", "All electrical burns get the backup paramedic response, as do 2nd/3rd degree burns over major body areas.", "Any child under 18 months with any listed emergency (plus dehydration, hypo/hyperthermia, poor muscle tone, failure to feed) gets the backup response.", "Any other medical emergency gets the nearest fire suppression unit only, which treats the patient and decides if an ALS unit or Rescue is needed."]},
  {id:"MP-205.06-Staging", title:"Staging Levels I and II", group:"Volume 2", what:"The standard system for parking responding apparatus before Command assigns it — Level I (automatic) and Level II (central reserve).", points:["Level I staging is automatic for all incidents with 3 or more companies responding.", "First engine and first ladder go straight to the scene; all other units stage in their direction of travel, uncommitted, about one block from the scene.", "Staged companies announce arrival with company designation and staged direction ('Engine One, South'); no acknowledgement is needed, and they stay off the air until ordered.", "Units never self-assign.", "Level II staging is used for all greater-alarm incidents and puts all reserve resources in one central location with a Staging Sector Officer.", "When Level II is activated, Command gives an approximate location and requests a separate radio channel for the Staging Sector.", "If no Staging Officer is assigned, the first fire officer to arrive at the staging area automatically becomes Staging Officer.", "Crews leaving staging stand by their unit with crew intact and warning lights off until assigned."]},
  {id:"MP-205.07-Apparatus-Placement", title:"Apparatus Placement", group:"Volume 2", what:"Where to put apparatus on the fireground so placement serves the tactics instead of limiting them.", points:["Apparatus function should regulate placement — poor placement limits the functions a unit can be assigned.", "Later-arriving companies stage a minimum of one block short of the immediate fire area and remain uncommitted until ordered in by Command.", "Working apparatus should generally sit at least 30 feet from involved buildings, even with nothing showing; greater distances are indicated in many situations.", "Avoid 'belly to butt' placement; maintain an access lane down the center of streets where possible.", "Think of apparatus as an expensive exposure; anticipate heat release with structural collapse and forecast where the fire is going.", "Never park where the apparatus cannot be repositioned easily — especially spots with only one way in or out, like yards, alleys and driveways.", "Beware overhead power lines when positioning; do not park where lines may fall.", "Key positions first: place initial pumpers where they have maximum attack access and a strong water supply before access is blocked.", "When high volume is indicated, provide two pumped supply lines; use hydrants close to the fire before laying to distant ones.", "If apparatus becomes endangered, activate the engine sprinkler system and operate hoselines between it and the fire while repositioning."]},
  {id:"MP-205.07A-Safe-Parking", title:"Safe Parking While Operating in or Near Vehicle Traffic", group:"Volume 2", what:"How to park apparatus to shield crews, patients and the work area from moving traffic.", points:["Never trust the traffic; always wear a high-visibility reflective vest near vehicle traffic.", "Angle apparatus 45 degrees away from curbside where possible to direct motorists around the scene.", "For a first-arriving engine that may need a charged line, angle the engine so the pump panel is 'downstream,' opposite oncoming traffic.", "At night, turn OFF apparatus headlights to reduce blinding drivers; reduce other lighting to yellow lights and flashers.", "Always exit on the curb side / non-traffic side when possible, and look before stepping out.", "Cone/flare start distances: 65 ft at 25 mph, 105 ft at 40 mph, 160 ft at 60 mph; place and retrieve cones while facing oncoming traffic.", "On freeways, place the last cone about 160 ft 'upstream'; bring Rescues in one or two at a time.", "Establish a liaison with DPS as soon as possible on freeway incidents."]},
  {id:"MP-205.08-Driver-Safety", title:"Driver Safety", group:"Volume 2", what:"Minimum standards for driving and emergency response — speed limits, intersections, seat belts, and Code 3 rules.", points:["All personnel wear seat belts at all times in a City vehicle; no riding on tailboards or in exposed positions, ever.", "Code 3 maximum: 10 mph over the posted speed limit; 20 mph max when traveling in center or oncoming traffic lanes.", "In center or oncoming lanes, complete stop at all stop signs and traffic lights regardless of light color; with traffic, complete stop at all red lights and stop signs.", "In active school zones, do not exceed the posted speed limit even Code 3; consider Code 2.", "Water Tenders are not permitted to respond Code 3.", "Rescue units cannot upgrade to Code 3 on their own — only as directed by the responding or on-scene company officer.", "Code 3 requires two PFD members in the front seats when possible; the co-driver is a second set of eyes and announces clear/not clear at required stops.", "Avoid backing whenever possible; if no spotter is available the driver dismounts and walks completely around the apparatus first.", "A left-hand turn lane used for forward travel counts as an oncoming traffic lane — complete stop, unless turning under a protected green arrow.", "Exceeding allowable speed by 10 mph or more, or running a controlled intersection without stopping, is a major deviation reported up the chain of command."]},
  {id:"MP-205.08A-Spotting-Apparatus", title:"Spotting Fire Department Apparatus", group:"Volume 2", what:"The backing and spotting rules — signals, spotter positions, and when spotters are required.", points:["Avoid backing whenever possible; where backing is unavoidable, spotters shall be used.", "With only the driver aboard and no spotters available, the driver gets out and does a complete 360-degree survey first.", "A primary spotter is designated and the backing plan and signals are agreed on before moving; the primary spotter is usually at the left rear corner.", "When backing engine or ladder apparatus, all crew except driver/tiller dismount and act as spotters, including the company officer.", "Rear spotters stay 10-15 feet behind the apparatus and in position to see the driver's eyes in the side mirror.", "If the driver loses sight of the primary spotter, stop immediately until the spotter is visible again.", "Never back faster than spotters can safely walk backwards.", "STOP signal: both arms crossed with hands making a fist; STRAIGHT BACK: two hands above head, palms toward face, waving back.", "At night use flood lights, never flashlights, to signal the driver; spotters wear orange vests in traffic."]},
  {id:"MP-205.10-Ladder-Tender", title:"Ladder Tender Response", group:"Volume 2", what:"When the smaller ladder tender can run instead of the full ladder truck, and when to call for the big truck.", points:["A ladder tender extends the service life of the larger, costlier apparatus while providing a full level of truck capabilities.", "From quarters, a complete crew responds on the Ladder Truck to all structural assignments of 3-1 or greater; the officer may also bring the tender for a two-piece company.", "If dispatched while out in the tender, the company responds in the tender and Dispatch must be told so the TRO can relay it to all units.", "A two-piece company officer may respond to a BLS dispatch with a minimum four-member crew on the tender.", "Rule: when in doubt whether the tender is adequate, request a Ladder company backup."]},
  {id:"MP-205.15-Freeway", title:"Freeway Response", group:"Volume 2", what:"Freeway incident playbook: dispatch info, approach, DPS coordination, apparatus placement, and the freeway glossary.", points:["Units respond Code 2 on the freeway mainline; alternating headlights and rear flashers may be used.", "Travel against normal traffic flow only at DPS's specific request, when all traffic is stopped — and confirm traffic is stopped first.", "If access is a problem or direction of travel is unknown, Dispatch may send companies from opposite directions.", "On multi-unit responses, the first unit within a mile of the incident reports identity, location and direction; others stage Level I, preferably near an on-ramp.", "Place apparatus between oncoming traffic and operating personnel; leave one crew member (usually the Engineer) to watch traffic and set warning devices until DPS arrives.", "Only the apparatus absolutely necessary goes onto the freeway; all other units stage off the freeway.", "Unified Command post includes Fire, DPS, ADOT, and city police if traffic is diverted to city streets.", "Lane numbering: No. 1 is the lane nearest the median, excluding the HOV lane."]},
  {id:"MP-205.15A-Papago-Tunnel", title:"Papago Tunnel Response", group:"Volume 2", what:"Response guide for the I-10 Papago Tunnel — layout, water supply, radios, and the four major incident scenarios.", points:["Tunnel runs Third Avenue to Third Street; most direct access is Seventh Avenue and Seventh Street; no direct access from above (Hance Park).", "Two vehicular tunnels, five lanes each direction plus two emergency lanes; max traffic about 8,000 autos/hour/tunnel.", "Hydrant cabinets about every 300 ft on alternating sides (600 ft same side), 2.5-inch and 4-inch fittings; HUMAT valves will NOT fit in the hydrant boxes — direct hose connection required.", "No water supply in the central Bus Transit Tunnel; it is reached through fence gates and four access doors about one-third of the way in.", "Radio repeaters cover Fire Channels 1, 5, 8; repeat company identity twice at the start of a transmission because the repeater clips the first half-second.", "Emergency telephone cabinets every 150 ft on both sides; UPS gives 15 minutes of bridge power between APS loss and generator start.", "Level II staging on Culver Street just west of Central, at the standpipe connection.", "For a major fire: confirm exhaust fans at maximum in the needed direction, sump pumps off, lighting at maximum, SCBA on before entry, and assign an engine to pump the Culver Street standpipe."]},
  {id:"MP-205.20-Power-Lines", title:"Response to Power Lines/Energized Electrical Equipment", group:"Volume 2", what:"How to work around downed power lines and energized equipment without becoming the path to ground.", points:["Downed lines must always be considered energized with potentially lethal current; lines can re-energize by recloser, manual switch, induction, or backfeed.", "You cannot tell the voltage of a power line by the size of the conductor, and most overhead conductors are not insulated.", "Step potential: voltage in the ground drops with distance from the contact point; a tingling in the feet is a warning to back away; worse when the ground is wet.", "Hose streams conduct current — never spray directly into power lines; use a fog spray at the base of the pole, in short bursts.", "Never spray water onto electrical equipment until a utility rep confirms it is de-energized ('dead').", "Occupants of a vehicle in contact with lines stay inside; if they must leave, jump free without touching vehicle and ground at once, then walk away with very small steps.", "Do not make entry or fire attack on a substation, transformer, vault or pole fire until the utility rep verifies de-energization.", "Equipment is classed Energized, De-energized (cannot be 100% guaranteed), or Dead (confirmed by utility after grounding)."]},
  {id:"MP-206.01-Violent-Incidents", title:"Operations at Violent Incidents", group:"Volume 2", what:"The strategy for working violent incidents — same decision model as the fireground, with PD owning hazard mitigation.", points:["Same strategic decision model as the fireground: size-up, risk management, strategy, IAP, tactical objectives, review and revision.", "Risk rules: risk a lot, in a calculated manner, to save savable lives; risk a little for savable property; risk nothing for what is already lost.", "Inner perimeter is the Hot Zone — Fire/EMS never operate inside it; the warm zone between inner and outer perimeters is where triage, extrication and treatment happen under a coordinated plan with PD.", "Offensive strategy = entering a well-defined warm zone to treat/extricate; defensive = staging outside the hazard zone until safe.", "TLO (C958) is the 24-hour law-enforcement liaison for fire units and the key source of real-time info on perimeters and police actions.", "Direct communication with PD — face to face or on the PD tactical channel — is the best information gathering.", "If caught in an unpredicted violent situation: run, hide, fight — remove yourself to safety, call PD on their tactical channel, use the emergency traffic button if unsafe to speak, engage the aggressor only as an absolute last resort.", "Firefighters work in a minimum of pairs, better as an intact crew; maintain defensible space around patients."]},
  {id:"MP-206.01A-Civil-Unrest", title:"Guidelines for Civil Unrest", group:"Volume 2", what:"Supplemental guidance for civil unrest — safety rules, tactics, and coordination with law enforcement.", points:["No single-company responses are permitted inside the predefined area (geo fence).", "All responses are coordinated with law enforcement and include force protection/escort.", "Avoid sirens and air horns inside the immediate area; lights may be used.", "Park apparatus for rapid, unobstructed retreat and to best protect the crew.", "Patients are usually best treated by removing them from the scene to a treatment area (scoop and run); law enforcement brings patients to fire units.", "When no lives are at stake, emphasis is on protecting savable property; fully involved buildings with little exposure problem may be left to burn.", "Suppression emphasis: fast water, heavy streams, then get out; routine salvage, ventilation and overhaul may be discontinued; roof operations avoided.", "All fire units enter, travel, operate and return as intact groups with law enforcement.", "Chief officers are added to all responses in known civil unrest areas; Terrorism Liaison Officers should be used at tactical and strategic levels."]},
  {id:"MP-206.03-Supervising-Less-Experienced", title:"Supervising Less Experienced Personnel", group:"Volume 2", what:"Who counts as 'less experienced,' and how the company officer supervises them at working incidents.", points:["'Less experienced' = a probationary firefighter, or any member with less than two years total experience in fire fighting duties.", "Two years does not automatically make someone experienced — they may still need direct supervision.", "The company officer determines experience level by interview, evaluating proficiency (hose lays, SCBA, ladders, evolutions), training, and follow-up evaluation.", "Inexperienced firefighters are directly supervised by the company officer or a firefighter with more than two years total fire fighting experience.", "Direct supervision is required the moment they enter an area exposing them to potential injury or death — e.g. a smoke/fire building, a collapse area, a hazmat incident, or anywhere hazard tape is present.", "The whole crew shares responsibility for a new or less experienced firefighter."]},
  {id:"MP-206.05-Power-Saws", title:"Operating Power Saws", group:"Volume 2", what:"Safety and operating rules for rescue saws and chain saws on the fireground.", points:["Full protective clothing for the operator and anyone close by; face shield down; clothing completely buttoned up around moving belts, chains and blades.", "Carry the rescue saw engine stopped, blade frontward, muffler away from the body; carry the chain saw engine stopped, guide bar and chain to the rear, muffler away.", "Keep both hands on the controls with thumbs and fingers encircling the handles; make sure of footing first.", "Cutting is a two-firefighter job where possible: an operator and a guide.", "Plan before cutting: location and sequence of cuts, wind direction, and at least two means of egress.", "Operating a power saw above chest height is extremely hazardous — only under the direct order and/or supervision of an officer.", "Use of a power saw from ladders is not recommended if there are alternatives; use the carrying strap so both hands are free on the ladder.", "Never force the saw; side pressure or twisting can break or shatter the blade.", "Never refuel with the engine running; do not operate a saw with a fuel leak; examine the cutting wheel for nicks or defects at the start of each shift and after each use.", "Do not operate power saws in suspected flammable/explosive atmospheres."]},
  {id:"MP-206.09A-Police-SAU", title:"Police Department SAU Operations", group:"Volume 2", what:"How fire companies stand by for Phoenix PD Special Assignment Unit operations — stealth, staging, and who is in command.", points:["SAU standby is for medical assistance if an officer or civilian is injured; fire personnel will NOT join law enforcement assault operations and will NOT enter an area that is not secure.", "All fire communications on SAU incidents go primarily through C958 on an encrypted channel; units avoid radio traffic about the nature of the incident or the address.", "The nearest ALS fire company and rescue company are dispatched; response is Code 2 unless C958 requests Code 3.", "C958 acts as initial Incident Commander and establishes unified command with the PD supervisor; C958 is the liaison between PD and fire resources.", "Fire units stage outside the police control perimeter and out of any possible line of gunfire; C958 picks the staging location once the target address is known.", "C958 requests a premise alert for a minimum of one-quarter (1/4) mile around the target address so no other fire resources are dispatched into it.", "If medical standby runs longer than 2 hours, consider rotating companies.", "At no time should fire personnel operate within an active law enforcement inner perimeter."]},
  {id:"MP-206.14-Africanized-Honey-Bees", title:"Africanized Honey Bees", group:"Volume 2", what:"Rescue and treatment response to Africanized honey bee attacks — the fire department does not exterminate bees.", points:["Policy: the Fire Department does not exterminate bees; units deploy to rescue and/or treat victims of an attack.", "Dispatch sends two fire units (one ALS engine company and one ladder company) plus a Battalion Chief, Code III.", "Arrive about 150 feet from the colony, careful not to commit into the path of the bees.", "Three crew members don full structural PPE including SCBA; tape ankles and waist tight so bees cannot crawl up; bee PPE may be worn instead if available.", "Attack with a quick 1.75-inch line at a quick pace, fog pattern sweeping the air around firefighters and patient; retreat to about 150 feet from the swarm.", "Class A foam may be used at the highest concentration possible to help water adhere to the bees; Class B foams containing PFAS should NOT be used.", "Call takers ask whether the incident is within 200 feet of a school, day care or building with many occupants; if so, occupants are told to stay indoors and close all external openings."]},
  {id:"MP-206.21-Light-Rail", title:"Light Rail Operations", group:"Volume 2", what:"Hazards and response procedures for the Valley Metro light rail system — overhead power, derailments, fires, and access.", points:["Overhead contact system (OCS) is 750-950 volts DC, 2,000-6,000 amps; wires tensioned at 5,000 lbs (top) and 3,000 lbs (bottom) and will whip if severed.", "Normal OCS height is 18 feet; lowest point is 14.5 feet at the Washington/SR-143 underpass — lower lights and flags when crossing.", "LRV: 90 ft long, 12 ft high, 9 ft wide, 103,000 lbs empty, 200-person max, normal max speed 35 mph, about 190 ft stopping distance at 35 mph.", "Track switches move without warning and exert 1,200 lbs of force — they will crush hands or feet.", "Traction power substations about every mile; emergency trip switch (ETS) is outside the door in a Knox box; pushing it shuts down AC in and DC out and signals adjacent substations.", "If an LRV is derailed with the pantograph still on the OCS, do not touch the LRV; have the operator lower the pantograph or de-energize the OCS.", "De-energize via OCC remote shutdown (Option 1) or the ETS at the nearest TPSS (Option 2); either way, get a Transportation Supervisor with a Hot Stick to confirm it is dead before touching the LRV.", "Easiest access is through the LRV doors via exterior emergency door releases; windows are extremely hard to break and cutting the body does not give adequate access.", "OSHA requires 10 feet clearance from the OCS for apparatus, ladders and equipment; straight streams must not contact the energized OCS.", "Laying supply lines across tracks is a last resort — if done, the IC must tell the Alarm Room so light rail traffic is shut down for that section."]},
  {id:"E-One-Mid-Mount-Ladder-Manual", title:"E-One Mid-Mount Ladder Manual (95' Platform)", group:"Apparatus/Hydraulics", what:"Operator manual bundle for the E-One 95-foot mid-mount platform (Typhoon chassis) — safety, interlocks, controls, and aerial operation.", points:["The aerial assembly is not insulated — keep it at least 10 feet from overhead power lines.", "Under the Stabilizers Set interlock, the aerial will not operate unless the stabilizers are deployed.", "Do not operate the aerial with either the front-to-back or side-to-side level indicator in the red zone; green or yellow is allowed.", "Inspect the aerial, waterway, outriggers, cables and hydraulic system daily, and especially after use.", "Do not operate the aerial during a lightning storm; do not leave the turntable unattended with the aerial raised or extended.", "Never move the vehicle with the aerial out of the stowed position; never use the aerial as a crane or battering ram.", "Personnel must wear safety belts at the tip of the ladder; do not climb the aerial while it is moving.", "Aerial operations are not recommended with wind speeds over 35 mph.", "In cold climates, drain the waterway after use to prevent freeze-up damage."]},
  {id:"Ladder-9-Manual", title:"Ladder 9 Operator Manual (E-One 100' HR Aerial)", group:"Apparatus/Hydraulics", what:"Operator manual bundle for Ladder 9 — an E-One Typhoon chassis with a 100-foot HR aerial (safety, load chart, activation, and aerial operation).", points:["The aerial assembly is not insulated — keep it at least 10 feet from overhead power lines.", "The interlock will not allow aerial operation until the outriggers are properly set.", "Do not raise, rotate or extend the aerial until outriggers are set; never move the vehicle with the aerial out of the stowed position.", "The operator at the driver's pump panel should stand on the anti-electrocution platform any time the aerial is in operation.", "Personnel must wear safety belts at the tip of the ladder, and must not climb the aerial while it is moving.", "Do not use the aerial as a crane, battering ram, or leverage device; use it cantilevered only, positioned about 6-12 inches above a structure.", "Aerial operations are not recommended with wind speeds over 35 mph.", "Distribute weight evenly on the aerial — 10 feet between personnel is recommended; never exceed the published load limits; check the load and reach charts, don't rely on memory.", "Outrigger pads must not bridge curbs, ditches, gullies, runoff drains, or manhole covers; use wheel chocks under the front wheels.", "Do not operate the aerial during a lightning storm; do not leave the turntable unattended with the aerial raised or extended."]},
  {id:"Pierce-Impel-Manual", title:"Pierce Velocity/Impel Operator's Manual", group:"Apparatus/Hydraulics", what:"Pierce Velocity/Impel chassis operator's manual — safety, pre-trip, driving, and emergency procedures for the truck itself.", points:["Backing: always use a spotter; blind spots can extend up to 16 feet in front and 160 feet behind a medium truck.", "Heavy trucks have a significantly higher rollover tendency due to a higher center of gravity — avoid sharp turns at excessive speeds and abrupt maneuvers; always buckle up.", "The vehicle is not insulated: keep boom and vehicle 10 ft from power lines; electricity can arc across a gap as large as 10 feet.", "If the vehicle contacts a power line, stay inside unless there is a fire; if you must leave, jump completely clear, landing with both feet together, and never touch vehicle and ground at the same time.", "High-pressure hydraulic fluid at pressures as low as 100 psi can penetrate skin — never search for leaks with your hands; use wood or cardboard.", "Water fording is not recommended; never ford water that could partially submerge the axles, and if fording, keep speed at or below 5 mph.", "Daily pre-trip inspection covers the interior, exterior and brake testing before the vehicle goes in service."]},
  {id:"Pumping-Sequence", title:"Pumping Operations — Pumping Sequence", group:"Apparatus/Hydraulics", what:"The engineer's step-by-step pumping sequence — spotting, cab procedures, tank and hydrant water, foam, hydraulics, and troubleshooting.", points:["Lay supply line at max 15 mph, slowing to 3-5 mph on the fireground; spot at least 30 feet from the structure or the height of the structure, whichever is greater.", "Foam on tank water: turn on foam and set to 0.3%; if no foam is produced, raise to 0.5%.", "Engine pressure formula: EP = NP + FL + AP ± EL; elevation is 1/2 psi per foot, or 5 psi per floor above the first.", "Nozzle pressures: TFT 75 psi, smooth bore 50 psi (handline) and 80 psi (master stream); fog master stream 100 psi.", "Smooth bore flows at 50 psi: 1-inch 200 gpm, 1-1/8-inch 250 gpm, 1-1/4-inch 300 gpm; master stream smooth bore at 80 psi: 1-3/8-inch 500, 1-1/2-inch 600, 1-3/4-inch 800, 2-inch 1,000 gpm.", "Friction loss (handline): FL = (GPM x HS - 10) / 10 per 100 ft, where HS is 4 for 1.5-inch, 3 for 1.75-inch, 2 for 2-inch hose.", "Appliance loss only at 350 gpm or greater: gated wye 10 psi, RPM/stang gun 15 psi, standpipe 20 psi.", "Lost supply line: close intake, open tank-to-pump, shut down exterior/exposure lines, regain pressure, then notify Command via emergency traffic for interior crews to exit.", "A centrifugal pump overheats if run without moving water — open the tank fill partially to recirculate, or flow water; a fully open tank fill can cause cavitation."]},
  {id:"LaFrance-Platforms", title:"American LaFrance/LTI Aerial Platforms", group:"Apparatus/Hydraulics", what:"Step-by-step setup and operation of the American LaFrance/LTI aerial platform — outriggers, controls, and shutdown.", points:["Operate the aerial only on concrete or asphalt — any other surface is extremely hazardous due to unknown soil conditions.", "Always use ground plates regardless of surface; turn the handles toward the truck.", "Extend outrigger beams fully first, then lower the jacks; jacks go down until the bulge in the rear tires is removed and the green lights come on.", "Level the truck so the float is in the green area (3% of grade); set all four pins in the outrigger jacks with about 1/4-inch clearance above the locking pin.", "Controls are always operated in sequence: elevate, rotate, extend; both hands on the levers, smooth operation.", "Short jacking: beams not fully extended on one side — the aerial must be operated over the fully extended side, NEVER over the short-jacked side, and the override switch must be held to move the aerial.", "The front bumper jacks deploy until the green light comes on, then hold for 5 seconds.", "To bed the aerial, retract, rotate and lower in reverse order, then hold the elevate lever down 3-5 seconds to secure it in the cradle.", "Ladder 20 and 50 have a remote outrigger panel in the left rear compartment, operable about 20 ft behind the truck."]},
  {id:"Pretrip-Inspection", title:"Pre-trip Inspection / Daily Check", group:"Apparatus/Hydraulics", what:"The daily pre-trip / daily check — engine compartment, under the truck, cab, pump panel, and the air brake test.", points:["Engine oil level: check at least 30 minutes after shut down; transmission fluid: engine running, in neutral, at operating temperature.", "Tire tread minimums: DOT 4/32-inch front, 2/32-inch rear; call RM-14 at 6/32-inch; brake pads/shoes minimum 1/4-inch thickness.", "Slack adjusters: 1 to 1.5 inches normal on a manual pull, 1.5 to 2 inches on brake application.", "Air leakage test (tanks full, engine off, parking brake released): loss less than 2 psi in 1 minute for a single vehicle, less than 3 psi for a combination vehicle.", "With the foot brake firmly applied, pressure must not drop more than 3 psi in 1 minute (single) or 4 psi (combination) after the initial drop.", "Low-pressure warning must come on before pressure falls below 60 psi.", "Spring brakes: the 'Parking Brake' knob should pop out when pressure falls to 20-40 psi.", "Air pressure must build from 85 to 100 psi within 45 seconds in dual air systems (engine on, parking brake on, high idle on).", "Governor cut-in about 100 psi, cut-out about 120-125 psi."]},
  {id:"Ladder-Manual-Ch2-Building-Construction", title:"Building Construction", group:"Ladder Manual", what:"How buildings are built and how fire breaks them — the construction knowledge that drives size-up and collapse prediction.", points:["All structures are designed to transfer weight to the ground; all will eventually collapse, and fire speeds that up — knowing how components fail tells you roughly when.", "Four basic styles: masonry, frame, metal, concrete.", "Unreinforced masonry (mostly pre-late-1940s brick) is identified by a 'king's row,' usually every six courses; walls can collapse easily if roof or floor sections fail and push or pull on them.", "Parapets are common on unreinforced masonry and pose substantial collapse potential from hose streams and cantilevered overhangs.", "Reinforced masonry (CMU/block, post-late-1940s, steel-reinforced after the mid-70s) is far stronger laterally.", "Conventional framing (primary before 1960): 2x4 or 2x6 rafters and ridge beams; interior walls running with the ridge are usually bearing walls.", "Lightweight trusses (gusset plates patented 1959): engineered triangles, top cord in compression, bottom cord in tension; each member depends on the others — cut one and the truss can fail.", "Lightweight trusses are designed to be supported by the ends only; the bottom cord is unsupported.", "A false mansard is generally not fire stopped and acts basically as a horizontal chimney.", "Balloon framing has straight wall runs with no fire stops from first to second floor — fire runs the wall."]},
  {id:"Ladder-Manual-Ch6-Size-Up-Tactics", title:"Size Up & Tactics", group:"Ladder Manual", what:"Ladder-company size-up: a continual process from dispatch until the incident is over.", points:["Size-up begins at dispatch and is not complete until the incident is over; conditions change fast, so re-evaluate constantly.", "Pre-fire planning is one of the most useful size-up tools — crews see the building when it is not on fire.", "Spot ladder apparatus so it will not have to move if the operation shifts from offensive to defensive.", "Ladder crews keep asking: where is the fire relative to the roof, how long has it burned, what is the construction, where is it going, is it impinging on roof supports?", "Pre-1970s construction used unreinforced or under-reinforced masonry; pre-1960s roofs were conventional framing with wide-span trusses and no lightweight trusses; gusset plates began in 1960; OSB began in the 1980s.", "Smoke tells the story: attic fire shows at gable vents/roof turbines; interior fire shows at windows and doors.", "If fire is contained to the attic, keep the attic intact and use a penetrating nozzle or a 1.5-inch nozzle through the ceiling — vertical ventilation is not initially recommended.", "No vertical ventilation when the fire has self-vented or the building is fully involved.", "Ladder companies are not to go up on residential tile roofs."]},
  {id:"Ladder-Manual-Ch13-Roof-Types", title:"Roof Types and Construction", group:"Ladder Manual", what:"The roof types ladder crews will meet and which ones can — and cannot — be vertically vented.", points:["Metal roofs: light-gauge panels, cut with chain or circular saw; very slippery when wet.", "Metal clad buildings: lightweight construction, fail early; should NOT be vertically vented; skylights of thin Plexiglas/fiberglass blend in with the tin and break under a firefighter's weight.", "Foam roofs can be over 2 inches thick and hide problems — probing is essential; ponded water adds thousands of pounds of live load.", "Lightweight concrete: saws fail early; a typical 4x6 hole spans several trusses and purlins; crews must be clear below the hole because cut panels fall; try natural or MPV ventilation before vertical.", "Textrum panels (4x8 compressed cooler-pad material) are best cut with a chain saw.", "Panelized roofs cover huge areas on few columns and fail quickly and over large areas when exposed to fire.", "Built-up areas can be 2 to 12 inches thick — saw choice must account for the thickness.", "A 10x10 ft area of water 2 inches deep adds 5 tons to the roof; drain pooled water before loading the roof with personnel.", "CMU roofs are unsuitable for vertical ventilation — the grouted, reinforced makeup cannot be breached with ladder-company tools.", "Bowstring trusses are spaced 15-25 ft apart; failure of one truss can collapse a large part of the roof; if fire involves the structure or roof, no traditional vertical ventilation."]},
  {id:"Ladder-Manual-Ch23-Vehicular-Extrication", title:"Vehicular Extrication", group:"Ladder Manual", what:"Vehicle extrication from scene security through patient packaging, airbags, and tools.", points:["A charged 1.5-inch hoseline with a firefighter in full PPE is required during extrication in case of fire.", "Stabilize the vehicle first: cribbing, flatten tires, or tie off unstable vehicles; cover airbags with a life-net.", "Disconnect the battery negative side first, then the positive — use battery power first if needed.", "One firefighter maintains patient stabilization throughout; protect the patient from glass and debris with blankets or tarps.", "Golden Hour: survival improves when the patient is extricated, packaged and transported within an hour of emergency personnel arriving.", "Late-model luxury vehicles (1995 or later) may have 6-8 airbags, seatbelt pretensioners and laminated glass.", "Always treat undeployed airbags and pretensioners as live; stay out of the deployment path; an undeployed airbag can deploy up to 30 minutes after the battery is disconnected.", "The compressed gas cylinder is generally in the C post — make cuts high on the A, B and C posts to avoid it.", "The Halmatro tool runs two tools at once off one power plant with two 20-ft hoses and uses vegetable oil as hydraulic fluid."]},
  {id:"Ladder-Manual-Ch26-Tree-Rescue", title:"Tree Rescue", group:"Ladder Manual", what:"Four-phase tree rescue — size-up, making the area safe, the rescue itself, and termination.", points:["Phase I: take command, secure a witness, call early for additional resources, assess hazards (overhead lines, tree condition, falling fronds, wind), and decide rescue vs. recovery early.", "The immediate rescue area is a 50-foot radius around the tree; remove all non-essential civilian and rescue personnel from it.", "Rescue order, low risk to high risk: talk the victim into self-rescue, ladder the tree with ground ladders, then climb the tree — climbing is a technical rescue for TRT members only.", "Ground ladders: first ladder under the victim, second alongside and slightly above; both secured to the tree with webbing or rope.", "Tree climbing requires two rescuers assigned by Extrication Sector; one climbs above and to the side to set a lowering-system anchor.", "Assess the victim's ABCs and exact entrapment on approach; if unconscious, rescue must be quick.", "Consider crew rotation in heat, hypothermia in cold, lighting if operations run into the night, and activating CISD for extraordinary incidents."]},
];
